                if (index == potion_index)
                    index = GetDynamicPotionDefIndex();
                else if (index == resurrection_index) {
                    index = GetDynamicResurrectionDefIndex();
                    if (index == 0)
                        gold += 20;
                }
                if (index > 0)
                    items.push_back(std::pair<long,CCharString>(index, ""));
            }
        }
    }
}

