    long next; int terminated; std::vector<std::string> played; std::vector<int> pushable; std::vector<int> scratch;
    Sim() : mi(0), workTime(true), look(FINISHED), ai(0), di(0), frame(100), fps(15), rnd(0.25f), next(-1), terminated(0) { }
